// Knowledge Base — app entry.
// Loads content/index.json (generated by scripts/build_index.py), then renders
// views based on the URL hash:  #/            -> home
//                               #/about       -> top-level page (content/about.md)
//                               #/<folder>    -> category / collection page
//                               #/<note>      -> note page

import { icon } from "./icons.js";
import { renderMarkdown } from "./markdown.js";
import { initSearch, openSearch, closeSearch } from "./search.js";
import * as store from "./store.js";

const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];
const main = $("#main");

const esc = (s = "") => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

const state = {
  index: null,
  nodes: new Map(),   // id -> node
  parents: new Map(), // id -> parent folder
  flat: [],           // all notes in reading order
};
const mdCache = new Map();
let tocObserver = null;

/* ------------------------------------------------------------------ data */

function indexTree(nodes, parent = null) {
  for (const node of nodes) {
    state.nodes.set(node.id, node);
    if (parent) state.parents.set(node.id, parent);
    if (node.type === "folder") indexTree(node.children, node);
    else state.flat.push(node);
  }
}

const notesUnder = (folder) =>
  folder.children.flatMap((c) => (c.type === "note" ? [c] : notesUnder(c)));

function ancestors(id) {
  const out = [];
  for (let p = state.parents.get(id); p; p = state.parents.get(p.id)) out.unshift(p);
  return out;
}

const rootOf = (id) => id.split("/")[0];
const displayName = (f) => f.short || f.title;

function fmtDate(iso) {
  if (!iso) return "";
  const d = new Date(iso + "T00:00:00");
  return isNaN(d) ? iso : d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

function latestUpdate(notes) {
  return notes.reduce((max, n) => (n.updated > max ? n.updated : max), "");
}

async function fetchNote(id) {
  if (!mdCache.has(id)) {
    const res = await fetch(`content/${id.split("/").map(encodeURIComponent).join("/")}.md`, { cache: "no-cache" });
    if (!res.ok) throw new Error(res.status);
    mdCache.set(id, await res.text());
  }
  return mdCache.get(id);
}

/* ------------------------------------------------------------ fragments */

function breadcrumbs(id, { includeSelf = true } = {}) {
  const sep = `<span class="sep">${icon("chevron")}</span>`;
  const parts = [`<a href="#/">Home</a>`];
  for (const a of ancestors(id)) parts.push(`<a href="#/${a.id}">${esc(displayName(a))}</a>`);
  const self = state.nodes.get(id) || state.index.pages[id];
  if (includeSelf && self) parts.push(`<span class="current">${esc(self.short || self.title)}</span>`);
  return `<nav class="breadcrumbs" aria-label="Breadcrumb">${parts.join(sep)}</nav>`;
}

function noteRow(node) {
  if (node.type === "folder") {
    const notes = notesUnder(node);
    return `
      <li class="note-item">
        <a href="#/${node.id}">
          <span class="ni-icon">${icon("folder")}</span>
          <span class="ni-title">${esc(node.title)}</span>
          <span class="ni-time">${notes.length} notes</span>
          <span class="ni-date">${fmtDate(latestUpdate(notes))}</span>
        </a>
      </li>`;
  }
  return `
    <li class="note-item" data-note="${esc(node.id)}">
      <a href="#/${node.id}">
        <span class="ni-icon">${icon("file")}</span>
        <span class="ni-title">${esc(node.title)}</span>
        <span class="ni-time">${node.minutes} min</span>
        <span class="ni-date">${fmtDate(node.updated)}</span>
      </a>
    </li>`;
}

function noteList(nodes, { head = true } = {}) {
  return `
    ${head ? `<div class="note-list-head"><span></span><span>Note</span><span>Reading</span><span style="text-align:right">Updated</span></div>` : ""}
    <ul class="note-list">${nodes.map(noteRow).join("")}</ul>`;
}

function folderCard(folder) {
  const notes = notesUnder(folder);
  return `
    <a class="card" href="#/${folder.id}">
      <span class="card-icon">${icon(folder.icon || "folder")}</span>
      <div>
        <h3>${esc(folder.title)}</h3>
        ${folder.summary || folder.description ? `<p>${esc(folder.summary || folder.description)}</p>` : ""}
      </div>
      <div class="card-foot">
        <span>${notes.length} notes</span>
        <span class="card-arrow">${icon("arrowRight")}</span>
      </div>
    </a>`;
}

/* ---------------------------------------------------------------- views */

function setLayout(kind) {
  document.body.classList.toggle("layout-home", kind === "home");
  document.body.classList.toggle("layout-docs", kind === "docs");
}

function renderHome() {
  setLayout("home");
  document.title = "Knowledge Base";
  const tree = state.index.tree;
  const cards = tree.flatMap((f) => (f.homeExpand ? f.children.filter((c) => c.type === "folder") : [f]));
  const recent = [...state.flat].sort((a, b) => (b.updated > a.updated ? 1 : -1)).slice(0, 5);
  const total = state.flat.length;

  main.innerHTML = `
    <div class="home">
      <section class="hero">
        <h1>Everything I've learned,<br><span class="muted">in one place.</span></h1>
        <p>A personal archive of study notes from the IT courses and certifications I've taken over the years.</p>
        <div class="hero-actions">
          <a class="btn btn-primary" href="#/${tree[0]?.id ?? ""}">Browse notes ${icon("arrowRight")}</a>
          <button class="btn btn-ghost" data-open-search>${icon("search")} Search notes</button>
        </div>
        <div class="home-stats">
          <span><strong>${total}</strong>notes</span>
          <span><strong>${tree.length}</strong>categories</span>
        </div>
      </section>

      <h2 class="section-title">Browse notes</h2>
      <div class="card-grid">${cards.map(folderCard).join("")}</div>

      <h2 class="section-title">Recently updated</h2>
      <div class="recent">${noteList(recent)}</div>
    </div>`;
}

function renderFolder(folder) {
  setLayout("docs");
  document.title = `${folder.title} · Knowledge Base`;
  const notes = notesUnder(folder);
  const directNotes = folder.children.filter((c) => c.type === "note");
  const subfolders = folder.children.filter((c) => c.type === "folder");
  // Folders that contain notes directly become accordions; folders of folders become cards.
  const accFolders = subfolders.filter((f) => f.children.some((c) => c.type === "note"));
  const cardFolders = subfolders.filter((f) => !accFolders.includes(f));

  main.innerHTML = `
    <div class="page">
      ${breadcrumbs(folder.id)}
      <header class="page-head">
        <h1 class="page-title">${esc(folder.title)}</h1>
        ${folder.description ? `<p class="page-desc">${esc(folder.description)}</p>` : ""}
        <div class="meta-row">
          <span class="meta">${icon("file")} ${notes.length} notes</span>
          ${subfolders.length ? `<span class="divider"></span><span class="meta">${icon("layers")} ${subfolders.length} sections</span>` : ""}
          ${notes.length ? `<span class="divider"></span><span class="meta">${icon("calendar")} Updated ${fmtDate(latestUpdate(notes))}</span>` : ""}
        </div>
      </header>

      ${cardFolders.length ? `<div class="card-grid" style="margin-bottom:32px">${cardFolders.map(folderCard).join("")}</div>` : ""}

      ${accFolders.length ? `
        <h2 class="block-title">Sections</h2>
        <div class="accordion">
          ${accFolders.map((f, i) => {
            const n = notesUnder(f);
            return `
              <details class="acc" ${i === 0 ? "open" : ""}>
                <summary>
                  <span class="chev">${icon("chevron")}</span>
                  <span class="title">${esc(f.title)}</span>
                  <a class="open-link" href="#/${f.id}">Open</a>
                  <span class="badge">${n.length} notes</span>
                </summary>
                ${noteList(f.children)}
              </details>`;
          }).join("")}
        </div>` : ""}

      ${directNotes.length ? `
        ${subfolders.length ? `<h2 class="block-title" style="margin-top:32px">Notes</h2>` : ""}
        <div class="list-card">${noteList(directNotes)}</div>` : ""}
    </div>`;
}

async function renderNote(note, isPage = false) {
  setLayout("docs");
  document.title = `${note.title} · Knowledge Base`;

  // Prev / next within the same top-level category
  const siblings = isPage ? [] : state.flat.filter((n) => rootOf(n.id) === rootOf(note.id));
  const i = siblings.indexOf(note);
  const prev = siblings[i - 1];
  const next = siblings[i + 1];

  main.innerHTML = `
    <div class="page">
      ${isPage ? "" : breadcrumbs(note.id)}
      <div class="note-layout">
        <article>
          <header class="page-head">
            <h1 class="page-title">${esc(note.title)}</h1>
            ${note.description && !note.placeholder ? `<p class="page-desc">${esc(note.description)}</p>` : ""}
            <div class="meta-row">
              ${note.updated ? `<span class="meta">${icon("calendar")} Updated ${fmtDate(note.updated)}</span><span class="divider"></span>` : ""}
              <span class="meta">${icon("clock")} ${note.minutes} min read</span>
            </div>
          </header>
          ${note.placeholder ? `<p class="placeholder-note">Placeholder content — real notes coming soon.</p>` : ""}
          <div class="prose" id="prose"><p style="color:var(--text-3)">Loading…</p></div>
          ${prev || next ? `
            <nav class="pager" aria-label="Previous and next note">
              ${prev ? `<a class="prev" href="#/${prev.id}"><small>← Previous</small><span>${esc(prev.title)}</span></a>` : ""}
              ${next ? `<a class="next" href="#/${next.id}"><small>Next →</small><span>${esc(next.title)}</span></a>` : ""}
            </nav>` : ""}
        </article>
        <aside class="toc" id="toc" aria-label="On this page"></aside>
      </div>
    </div>`;

  const prose = $("#prose");
  try {
    const md = await fetchNote(note.id);
    if (!prose.isConnected) return; // user navigated away meanwhile
    const baseDir = "content/" + note.id.split("/").slice(0, -1).map((s) => s + "/").join("");
    prose.replaceChildren(renderMarkdown(md, baseDir));
    buildToc(prose);
  } catch {
    prose.innerHTML = `<p>Could not load this note.</p>`;
  }
}

function buildToc(prose) {
  const toc = $("#toc");
  const heads = $$("h2, h3", prose);
  tocObserver?.disconnect();
  if (heads.length < 2) return;
  toc.innerHTML = `<div class="toc-title">On this page</div>` +
    heads.map((h) => `<a href="#" data-target="${h.id}" class="lvl-${h.tagName[1]}">${esc(h.textContent)}</a>`).join("");

  toc.addEventListener("click", (e) => {
    const a = e.target.closest("a[data-target]");
    if (!a) return;
    e.preventDefault();
    document.getElementById(a.dataset.target)?.scrollIntoView({ behavior: "smooth", block: "start" });
  });

  // Highlight the section currently in view
  const links = new Map($$("a", toc).map((a) => [a.dataset.target, a]));
  const visible = new Set();
  tocObserver = new IntersectionObserver((entries) => {
    entries.forEach((en) => (en.isIntersecting ? visible.add(en.target.id) : visible.delete(en.target.id)));
    const current = heads.find((h) => visible.has(h.id));
    if (current) links.forEach((a, id) => a.classList.toggle("active", id === current.id));
  }, { rootMargin: "0px 0px -70% 0px" });
  heads.forEach((h) => tocObserver.observe(h));
}

function renderNotFound() {
  setLayout("docs");
  document.title = "Not found · Knowledge Base";
  main.innerHTML = `
    <div class="empty">
      <h1>Note not found</h1>
      <p>This page doesn't exist or was moved.</p>
      <p><a class="btn btn-ghost" href="#/">Back home</a></p>
    </div>`;
}

/* -------------------------------------------------------------- sidebar */

function renderTree() {
  const build = (nodes) => `<ul>${nodes.map((n) => {
    if (n.type === "folder") {
      return `
        <li class="tree-folder${store.isOpen(n.id) ? " open" : ""}" data-id="${esc(n.id)}">
          <a class="tree-row" href="#/${n.id}">
            <span class="chev" data-toggle>${icon("chevron")}</span>
            <span class="label">${esc(displayName(n))}</span>
          </a>
          ${build(n.children)}
        </li>`;
    }
    return `
      <li class="tree-note" data-id="${esc(n.id)}">
        <a class="tree-row" href="#/${n.id}">
          <span class="dot">${icon("circle")}</span>
          <span class="label">${esc(n.title)}</span>
        </a>
      </li>`;
  }).join("")}</ul>`;

  $("#tree").innerHTML = build(state.index.tree);
  $("#topnav").innerHTML = state.index.tree.map((f) => `<a href="#/${f.id}" data-root="${esc(f.id)}">${esc(displayName(f))}</a>`).join("");
}

function updateNavState(id) {
  $$("#tree .tree-row.active").forEach((el) => el.classList.remove("active"));
  if (id) {
    const self = state.nodes.get(id);
    for (const a of [...ancestors(id), ...(self?.type === "folder" ? [self] : [])]) {
      const li = $(`#tree li[data-id="${CSS.escape(a.id)}"]`);
      if (li && !li.classList.contains("open")) {
        li.classList.add("open");
        store.setOpen(a.id, true);
      }
    }
    const row = $(`#tree li[data-id="${CSS.escape(id)}"] > .tree-row`);
    if (row) {
      row.classList.add("active");
      const tree = $("#tree");
      const r = row.getBoundingClientRect(), t = tree.getBoundingClientRect();
      if (r.top < t.top || r.bottom > t.bottom) row.scrollIntoView({ block: "center" });
    }
  }
  $$("#topnav a").forEach((a) => a.classList.toggle("active", !!id && rootOf(id) === a.dataset.root));
  $$(".sidebar-links a").forEach((a) => a.classList.toggle("active", (a.dataset.link === "home" && !id) || a.dataset.link === id));
}

/* --------------------------------------------------------------- router */

function route() {
  closeSearch();
  document.body.classList.remove("drawer-open");
  const path = decodeURIComponent(location.hash.replace(/^#\/?/, "")).replace(/\/+$/, "");
  tocObserver?.disconnect();
  window.scrollTo(0, 0);

  if (!path) renderHome();
  else if (state.index.pages[path]) renderNote(state.index.pages[path], true);
  else {
    const node = state.nodes.get(path);
    if (!node) renderNotFound();
    else if (node.type === "folder") renderFolder(node);
    else renderNote(node);
  }
  updateNavState(path);
  main.focus({ preventScroll: true });
}

/* ----------------------------------------------------------------- init */

function initChrome() {
  // Static icons
  $$(".brand-mark").forEach((el) => (el.innerHTML = icon("logo")));
  $$(".search-icon").forEach((el) => (el.innerHTML = icon("search")));
  $$("[data-icon]").forEach((el) => (el.innerHTML = icon(el.dataset.icon)));
  $("#menu-btn").innerHTML = icon("menu");
  $("#drawer-close").innerHTML = icon("x");
  $(".search-mobile").innerHTML = icon("search");
  $(".github-link").innerHTML = icon("github");
  const isMac = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);
  $$(".kbd-hint").forEach((el) => (el.textContent = isMac ? "⌘K" : "Ctrl K"));
  $("#year").textContent = new Date().getFullYear();

  // Theme
  const paintTheme = () => $$(".theme-toggle").forEach((b) => {
    const dark = store.currentTheme() === "dark";
    b.innerHTML = icon(dark ? "sun" : "moon");
    b.setAttribute("aria-label", dark ? "Switch to light theme" : "Switch to dark theme");
  });
  $$(".theme-toggle").forEach((b) => b.addEventListener("click", () => {
    store.setTheme(store.currentTheme() === "dark" ? "light" : "dark");
    paintTheme();
  }));
  matchMedia("(prefers-color-scheme: dark)").addEventListener("change", paintTheme);
  paintTheme();

  // Mobile drawer
  $("#menu-btn").addEventListener("click", () => document.body.classList.add("drawer-open"));
  $("#drawer-close").addEventListener("click", () => document.body.classList.remove("drawer-open"));
  $("#scrim").addEventListener("click", () => document.body.classList.remove("drawer-open"));
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      document.body.classList.remove("drawer-open");
      $("#lightbox").hidden = true;
    }
  });

  // Tree: chevron toggles a folder without navigating
  $("#tree").addEventListener("click", (e) => {
    const toggle = e.target.closest("[data-toggle]");
    if (!toggle) return;
    e.preventDefault();
    e.stopPropagation();
    const li = toggle.closest(".tree-folder");
    store.setOpen(li.dataset.id, li.classList.toggle("open"));
  });

  // Buttons rendered inside views
  main.addEventListener("click", (e) => {
    if (e.target.closest("[data-open-search]")) {
      openSearch();
      return;
    }
    const img = e.target.closest(".prose img");
    if (img && !img.closest("a")) {
      const lb = $("#lightbox");
      lb.querySelector("img").src = img.currentSrc || img.src;
      lb.querySelector("img").alt = img.alt;
      lb.hidden = false;
    }
  });
  $("#lightbox").addEventListener("click", () => ($("#lightbox").hidden = true));

}

async function init() {
  initChrome();
  initSearch();
  try {
    if (!window.marked) throw new Error("marked");
    const res = await fetch("content/index.json", { cache: "no-cache" });
    if (!res.ok) throw new Error("index");
    state.index = await res.json();
  } catch (err) {
    setLayout("home");
    main.innerHTML = err.message === "marked"
      ? `<div class="empty"><h1>Couldn't load the Markdown renderer</h1><p>Check your internet connection and reload.</p></div>`
      : `<div class="empty"><h1>Notes index not found</h1><p>Run <code>python scripts/serve.py</code> for local preview, or <code>python scripts/build_index.py</code> to generate it.</p></div>`;
    return;
  }
  indexTree(state.index.tree);
  renderTree();
  $("#sidebar-count").textContent = `${state.flat.length} notes`;
  window.addEventListener("hashchange", route);
  route();
}

init();
